// Проверка токена и сборка поста для Postiz
const req = $input.first().json;
const token = req.headers['x-pipeline-token'];
if (!$env.PIPELINE_WEBHOOK_TOKEN || token !== $env.PIPELINE_WEBHOOK_TOKEN) {
  throw new Error('unauthorized: неверный X-Pipeline-Token');
}
const b = req.body || {};
if (!b.video_url) throw new Error('нужно поле video_url');
if (!Array.isArray(b.channels) || b.channels.length === 0) {
  throw new Error('нужен массив channels: [{id, provider}] (id из GET /integrations)');
}
const caption = [b.caption_ru, b.caption_kz].filter(Boolean).join('\n\n');
const title = (b.title || caption.split('\n')[0] || 'Hitman').slice(0, 100);
return [{ json: {
  video_url: b.video_url,
  caption, title,
  publish_at: b.publish_at || null,
  channels: b.channels,
}}];

// Тело POST /posts. Настройки площадок сверяйте с docs.postiz.com/public-api
const d = $('Проверить и подготовить').first().json;
const media = $input.first().json; // ответ upload-from-url: {id, path, ...}
const settingsFor = (provider) => {
  switch (provider) {
    case 'youtube':
      return { __type: 'youtube', title: d.title, type: 'public' };
    case 'tiktok':
      return { __type: 'tiktok', privacy_level: 'PUBLIC_TO_EVERYONE', duet: true, stitch: true,
               comment: true, autoAddMusic: 'no', brand_content_toggle: false,
               brand_organic_toggle: false, content_posting_method: 'DIRECT_POST' };
    case 'instagram':
    case 'instagram-standalone':
      return { __type: provider, post_type: 'post' };
    default:
      return { __type: provider };
  }
};
return [{ json: {
  type: d.publish_at ? 'schedule' : 'now',
  date: d.publish_at ? new Date(d.publish_at).toISOString() : new Date().toISOString(),
  shortLink: false,
  tags: [],
  posts: d.channels.map(ch => ({
    integration: { id: ch.id },
    value: [{ content: d.caption, image: [{ id: media.id, path: media.path }] }],
    settings: settingsFor(ch.provider),
  })),
}}];
